#include <iostream>
#include <cstring>
#include <queue>
#include <algorithm>
#include <climits>
using namespace std;

const int MAX = 210;
const int INF = 0x3f3f3f3f;

int cap[MAX*MAX*2][MAX*MAX*2];
int f[MAX*MAX*2][MAX*MAX*2];
int level[MAX*MAX*2], count_level[MAX*MAX*2];
int n, t, src, dst;

int id(int r, int c) { return (r-1)*n + c; }
bool ok(int r, int c) { return r>=1 && r<=n && c>=1 && c<=n; }

void link(int u, int v, int c) { cap[u][v] += c; }

int dfs(int u, int lim) {
    if (u == dst) return lim;
    int pushed = lim, delta, min_level = n*n*2+2;
    for (int v = 0; v < n*n*2+2; ++v) {
        if (cap[u][v] - f[u][v] > 0) {
            if (level[u] == level[v] + 1) {
                delta = dfs(v, min(pushed, cap[u][v] - f[u][v]));
                f[u][v] += delta;
                f[v][u] -= delta;
                pushed -= delta;
                if (level[src] == n*n*2+2 || pushed == 0) return lim - pushed;
            }
            min_level = min(min_level, level[v] + 1);
        }
    }
    if (pushed == lim) {
        count_level[level[u]]--;
        count_level[min_level]++;
        if (count_level[level[u]] == 0) level[src] = n*n*2+2;
        level[u] = min_level;
    }
    return lim - pushed;
}

int max_flow() {
    if (src == dst) return INF;
    memset(f, 0, sizeof(f));
    memset(level, 0, sizeof(level));
    memset(count_level, 0, sizeof(count_level));
    int res = 0;
    while (level[src] < n*n*2+2) {
        res += dfs(src, INF);
    }
    return res;
}

struct Pos { int r, c, d; };

int dist[MAXN][MAXN];
bool vis[MAXN][MAXN];
char mat1[MAXN][MAXN], mat2[MAXN][MAXN];
int sx, sy;
const int dr[4] = {0,0,-1,1};
const int dc[4] = {-1,1,0,0};

void precompute() {
    queue<Pos> q;
    q.push({sx, sy, 0});
    memset(dist, 0x7f, sizeof(dist));
    memset(vis, 0, sizeof(vis));
    vis[sx][sy] = true;
    while (!q.empty()) {
        Pos cur = q.front(); q.pop();
        dist[cur.r][cur.c] = cur.d;
        if (cur.d > t) break;
        for (int k=0; k<4; ++k) {
            int nr = cur.r + dr[k], nc = cur.c + dc[k];
            if (ok(nr,nc) && mat1[nr][nc] != 'Y' && !vis[nr][nc]) {
                Pos nxt = {nr, nc, cur.d+1};
                vis[nr][nc] = true;
                q.push(nxt);
            }
        }
    }
}

void search_from(int r, int c) {
    queue<Pos> q;
    q.push({r, c, 0});
    memset(vis, 0, sizeof(vis));
    vis[r][c] = true;
    while (!q.empty()) {
        Pos cur = q.front(); q.pop();
        if (cur.d > t) break;
        if (dist[cur.r][cur.c] < cur.d) continue;
        if (dist[cur.r][cur.c] == cur.d && (mat2[cur.r][cur.c] < '1' || mat2[cur.r][cur.c] > '9')) continue;
        if (mat2[cur.r][cur.c] >= '1' && mat2[cur.r][cur.c] <= '9') {
            if (cur.r != r || cur.c != c) {
                link(id(r,c), id(cur.r,cur.c) + n*n, INF);
            }
            if (dist[cur.r][cur.c] == cur.d) continue;
        }
        for (int k=0; k<4; ++k) {
            int nr = cur.r + dr[k], nc = cur.c + dc[k];
            if (ok(nr,nc) && mat1[nr][nc] != 'Y' && !vis[nr][nc]) {
                Pos nxt = {nr, nc, cur.d+1};
                vis[nr][nc] = true;
                q.push(nxt);
            }
        }
    }
}

int main() {
    ios::sync_with_stdio(false); cin.tie(nullptr);
    cin >> n >> t;
    for (int i=1; i<=n; ++i) cin >> (mat1[i]+1);
    for (int i=1; i<=n; ++i) cin >> (mat2[i]+1);

    src = 0; dst = 2*n*n+1;

    for (int i=1; i<=n; ++i) {
        for (int j=1; j<=n; ++j) {
            if (mat1[i][j]>='1' && mat1[i][j]<='9') {
                link(src, id(i,j), mat1[i][j]-'0');
            }
            if (mat1[i][j]=='Z') { sx=i; sy=j; }
        }
    }

    for (int i=1; i<=n; ++i) {
        for (int j=1; j<=n; ++j) {
            link(id(i,j), id(i,j)+n*n, INF);
            if (mat2[i][j]>='1' && mat2[i][j]<='9') {
                link(id(i,j)+n*n, dst, mat2[i][j]-'0');
            }
        }
    }

    precompute();
    for (int i=1; i<=n; ++i) {
        for (int j=1; j<=n; ++j) {
            if (mat1[i][j]>='1' && mat1[i][j]<='9') {
                search_from(i,j);
            }
        }
    }

    cout << max_flow() << '\n';
    return 0;
}
